-- Catalogo India, versione 1 (IN-1).
-- GENERATO da scripts/seed-catalog.ts: non modificare a mano, rigenerare con `npx tsx scripts/seed-catalog.ts`.
-- Prerequisito: migrazioni supabase/migrations/20261106000100 … 20261106000500.
-- Idempotente: con la versione già pubblicata non scrive nulla e controlla solo i conteggi.
-- Tocca solo le tabelle del catalogo e la versione delle nazioni dei viaggi a righe; nessun dato di auth.
-- Dopo il controllo cancella le versioni precedenti della nazione (migrazione 20261119000000_cataloghi_superati.sql).

begin;

-- Prerequisiti: versione non superata, versione precedente pubblicata, tabelle dei traghetti presenti
do $pre$
begin
  if exists (select 1 from public.catalog_releases where country_code = 'IN' and status = 'pubblicata' and version > 1) then
    raise exception 'Il catalogo IN ha già una versione più recente di IN-1: questo seed è superato';
  end if;
  if to_regclass('public.place_photos') is null or to_regclass('public.place_tips') is null then
    raise exception 'Mancano le tabelle di foto e consigli: applicare prima supabase/migrations/20261110000100_foto_consigli.sql';
  end if;
end $pre$;

on conflict (code) do nothing;

on conflict (release_id) do nothing;

on conflict (place_key) do nothing;

-- Contenuto della versione: si scrive solo se è ancora in bozza
do $seed$
begin
  if not exists (select 1 from public.catalog_releases where release_id = 'IN-1' and status = 'bozza') then
    raise notice 'Versione IN-1 già pubblicata: nessuna scrittura, solo controllo';
    return;
  end if;




-- operators: nessuna riga

-- voyages: nessuna riga

-- route_ports: nessuna riga

-- place_links: nessuna riga


-- place_tips: nessuna riga

end $seed$;

update public.catalog_releases set status = 'pubblicata', published_at = now() where release_id = 'IN-1' and status = 'bozza';

-- Controllo finale: se fallisce, la transazione si annulla
do $check$
declare
  v_n bigint;
begin
  if not exists (select 1 from public.countries where code = 'IN' and currency = 'INR' and timezone = 'Asia/Kolkata' and language = 'hi') then
    raise exception 'Nazione IN: valuta, fuso o lingua diversi da quelli del seed';
  end if;
  perform now() at time zone 'Asia/Kolkata';
  if not exists (select 1 from public.catalog_releases where release_id = 'IN-1' and status = 'pubblicata') then
    raise exception 'Versione IN-1 non pubblicata';
  end if;
  select count(*) into v_n from public.regions where release_id = 'IN-1';
  if v_n <> 11 then raise exception 'regions (release_id = ''IN-1''): attese 11 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'IN-1';
  if v_n <> 302 then raise exception 'places (release_id = ''IN-1''): attese 302 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_texts where release_id = 'IN-1';
  if v_n <> 302 then raise exception 'place_texts (release_id = ''IN-1''): attese 302 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_sources where release_id = 'IN-1';
  if v_n <> 1337 then raise exception 'place_sources (release_id = ''IN-1''): attese 1337 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.operators where release_id = 'IN-1';
  if v_n <> 0 then raise exception 'operators (release_id = ''IN-1''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.voyages where release_id = 'IN-1';
  if v_n <> 0 then raise exception 'voyages (release_id = ''IN-1''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.route_ports where release_id = 'IN-1';
  if v_n <> 0 then raise exception 'route_ports (release_id = ''IN-1''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_links where release_id = 'IN-1';
  if v_n <> 0 then raise exception 'place_links (release_id = ''IN-1''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'IN-1' and category = 'porti';
  if v_n <> 5 then raise exception 'places (release_id = ''IN-1'' and category = ''porti''): attese 5 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'IN-1' and coords_status = 'verificate';
  if v_n <> 302 then raise exception 'places (release_id = ''IN-1'' and coords_status = ''verificate''): attese 302 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'IN-1' and official_url is not null;
  if v_n <> 129 then raise exception 'places (release_id = ''IN-1'' and official_url is not null): attese 129 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'IN-1' and wikidata_qid is not null;
  if v_n <> 302 then raise exception 'places (release_id = ''IN-1'' and wikidata_qid is not null): attese 302 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places where release_id = 'IN-1' and base_place_key is not null;
  if v_n <> 0 then raise exception 'places (release_id = ''IN-1'' and base_place_key is not null): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_photos where release_id = 'IN-1';
  if v_n <> 304 then raise exception 'place_photos (release_id = ''IN-1''): attese 304 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.place_tips where release_id = 'IN-1';
  if v_n <> 0 then raise exception 'place_tips (release_id = ''IN-1''): attese 0 righe, trovate %', v_n; end if;
  select count(*) into v_n from public.places p join public.place_keys k on k.place_key = p.place_key where p.release_id = 'IN-1' and k.country_code <> 'IN';
  if v_n <> 0 then raise exception 'Chiavi di luogo registrate per un''altra nazione: %', v_n; end if;
  select count(*) into v_n from public.places p where p.release_id = 'IN-1' and not exists (select 1 from public.place_texts t where t.release_id = p.release_id and t.place_key = p.place_key and t.lang = 'it');
  if v_n <> 0 then raise exception 'Luoghi senza testo italiano: %', v_n; end if;
  raise notice 'Catalogo IN-1 pubblicato e controllato: 302 luoghi, 0 crociere, 0 porti in rotta';
end $check$;

-- Versioni precedenti: cancellate (i viaggi passano a questa, che le contiene)
do $purge$
begin
  if to_regprocedure('private.purge_superseded_releases(text)') is not null then
    perform private.purge_superseded_releases('IN');
  end if;
end $purge$;

commit;
